\par \pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (ff. 13r\endash 14r) Kapitelverzeichnis bis Kap. 42; \plain \f1\i\lang1033\fs24  inc. \plain \f2\lang1032\fs24 \u945 \'e1\plain \f3\lang1033\fs24 V\plain \f4\lang1033\fs24 \u903 ? \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u8048 ? \u964 \'f4\u8055 ?\u956 \'ec\u8052 ? \u7952 ?\u958 \'ee \u7936 ?\u961 \'f1\u967 \'f7\u8134 ?\u962 \'f2 \u7952 ?\u957 \'ed \u964 \'f4\u8183 ? \u952 \'e8\u965 \'f5\u963 \'f3\u953 \'e9\u945 \'e1\u963 \'f3\u964 \'f4\u951 \'e7\u961 \'f1\u8055 ?\u8179 ? \u964 \'f4\u8055 ?\u952 \'e8\u949 \'e5\u964 \'f4\u945 \'e1\u953 \'e9 \u964 \'f4\u8048 ? \u964 \'f4\u8055 ?\u956 \'ec\u953 \'e9\u945 \'e1 \u948 \'e4\u8182 ?\u961 \'f1\u945 \'e1 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\i\lang1033\fs24  des. \plain \f2\lang1032\fs24 \u956 \'ec\u946 \'e2\plain \f3\lang1033\fs24 V\plain \f4\lang1033\fs24 \u903 ?\plain \f2\lang1032\fs24  \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ? \u964 \'f4\u8134 ?\u962 \'f2 \u7952 ?\u960 \'f0\u8054 ? \u964 \'f4\u8135 ? \u954 \'ea\u959 \'ef\u953 \'e9\u957 \'ed\u969 \'f9\u957 \'ed\u8055 ?\u8115 ? \u964 \'f4\u8182 ?\u957 \'ed \u956 \'ec\u965 \'f5\u963 \'f3\u964 \'f4\u951 \'e7\u961 \'f1\u8055 ?\u969 \'f9\u957 \'ed \u954 \'ea\u959 \'ef\u953 \'e9\u957 \'ed\u8134 ?\u962 \'f2 \u949 \'e5\u8016 ?\u967 \'f7\u945 \'e1\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2 \u954 \'ea\u945 \'e1\u8054 ? \u964 \'f4\u8182 ?\u957 \'ed \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2 \u964 \'f4\u8183 ? \u964 \'f4\u8051 ?\u955 \'eb\u949 \'e5\u953 \'e9\u964 \'f4\u8134 ?\u962 \'f2 \u7985 ?\u949 \'e5\u961 \'f1\u959 \'ef\u965 \'f5\u961 \'f1\u947 \'e3\u8055 ?\u945 \'e1\u962 \'f2 \u949 \'e5\u8016 ?\u967 \'f7\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24 . \endash (f. 14v) leer. \endash (f. 15r) Kap. 2, \u167 \'a7\u167 \'a7 3\endash 5; Z\u228 \'e4hlung nach \plain \f1\scaps\lang1033\fs24 Bornert\plain \f1\lang1033\fs24  \endash \plain \f1\scaps\lang1033\fs24 Gouillard\plain \f1\lang1033\fs24  \endash \plain \f1\scaps\lang1033\fs24 P\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 richon\plain \f1\lang1033\fs24  (Ms. \plain \f2\lang1032\fs24 \u945 \'e1\plain \f2\super\lang1032\fs24 \u959 \'ef\u957 \'ed\plain \f3\lang1033\fs24 V\plain \f1\lang1033\fs24 ); Textbeginn abweichend von der Ausgabe: \plain \f2\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\u963 \'f3\u8053 ?\u947 \'e3\u949 \'e5\u964 \'f4\u959 \'ef \u948 \'e4\u8182 ?\u961 \'f1\u945 \'e1\u964 \'f4\u8183 ? \u920 \'c8\u949 \'e5\u8183 ? \u960 \'f0\u945 \'e1\u961 \'f1\u8048 ? \u964 \'f4\u8182 ?\u957 \'ed \u960 \'f0\u945 \'e1\u955 \'eb\u945 \'e1\u953 \'e9\u8182 ?\u957 \'ed \u8037 ?\u963 \'f3\u960 \'f0\u949 \'e5\u961 \'f1 \u964 \'f4\u8048 ? \u967 \'f7\u961 \'f1\u965 \'f5\u963 \'f3\u8118 ? \u963 \'f3\u954 \'ea\u949 \'e5\u8059 ?\u951 \'e7 \plain \f4\lang1033\fs24 \u7970 ? \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u947 \'e3\u965 \'f5\u961 \'f1\u8118 ?, \u960 \'f0\u961 \'f1\u959 \'ef\u963 \'f3\u8053 ?\u947 \'e3\u949 \'e5\u964 \'f4\u959 \'ef \u954 \'ea\u945 \'e1\u8054 ? \u952 \'e8\u965 \'f5\u963 \'f3\u8055 ?\u945 \'e1\u953 \'e9 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24  (Kap. 2, \u167 \'a7 5) \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ? \u948 \'e4\u8182 ?\u961 \'f1\u945 \'e1 \u964 \'f4\u8055 ?\u956 \'ec\u953 \'e9\u945 \'e1 \u964 \'f4\u8183 ? \u920 \'c8\u949 \'e5\u8183 ? \u947 \'e3\u8055 ?\u957 \'ed\u949 \'e5\u964 \'f4\u945 \'e1\u953 \'e9 \u954 \'ea\u945 \'e1\u8054 ? \u954 \'ea\u945 \'e1\u955 \'eb\u949 \'e5\u8150 ?\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Bornert\plain \f1\lang1033\fs24  \endash \plain \f1\scaps\lang1033\fs24 Gouillard\plain \f1\lang1033\fs24  \endash \plain \f1\scaps\lang1033\fs24 P\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 richon\plain \f1\lang1033\fs24 , S. 49. \endash (ff. 15r\endash 18v) Kap. 5\endash 10 (Ms. \plain \f2\lang1032\fs24 \u946 \'e2\plain \f2\super\lang1032\fs24 \u959 \'ef\u957 \'ed\plain \f3\lang1033\fs24 V\plain \f1\lang1033\fs24  \endash \plain \f2\lang1032\fs24 \u950 \'e6\plain \f2\super\lang1032\fs24 \u959 \'ef\u957 \'ed\plain \f3\lang1033\fs24 V\plain \f1\lang1033\fs24  [\plain \f3\lang1033\fs24 \u245 \'f5V\plain \f1\lang1033\fs24  nicht numeriert]). \endash (ff. 18v\endash 19r) Kap. 11 A (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u949 \'e5\u966 \'f6.\u951 \'e7\plain \f3\lang1033\fs24 V\plain \f1\lang1033\fs24 , s. \plain \f1\i\lang1033\fs24  S\plain \f1\lang1033\fs24 , Hand a\plain \f4\lang1033\fs24 )\plain \f1\lang1033\fs24 . \endash (ff. 19r\endash 20r) zwischen 11 A und 11 B: Kapitel (im Ms. \plain \f2\lang1032\fs24 \u952 \'e8\plain \f3\lang1033\fs24 V\plain \f1\lang1033\fs24 ) \u252 \'fcber die allgemeine Bedeutung der Liturgie (Ms. \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\u8054 ? \u960 \'f0\u8049 ?\u963 \'f3\u951 \'e7\u962 \'f2 \u964 \'f4\u8134 ?\u962 \'f2 \u7985 ?\u949 \'e5\u961 \'f1\u959 \'ef\u965 \'f5\u961 \'f1\u947 \'e3\u8055 ?\u945 \'e1\u962 \'f2 \plain \f4\lang1033\fs24 \u7952 ?\plain \f2\lang1032\fs24 \u957 \'ed \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u8057 ?\u956 \'ec\u8179 ?\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\u8142 ?\u917 ?\plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u953 \'e9 \u948 \'e4\u8050 ? \u964 \'f4\u8134 ?\u962 \'f2 \u7985 ?\u949 \'e5\u961 \'f1\u959 \'ef\u965 \'f5\u961 \'f1\u947 \'e3\u8055 ?\u945 \'e1\u962 \'f2 \u964 \'f4\u8056 ? \u956 \'ec\u8050 ?\u957 \'ed \u7956 ?\u961 \'f1\u947 \'e3\u959 \'ef\u957 \'ed \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\i\lang1033\fs24  des. \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ? \u949 \'e5\u7988 ? \u964 \'f4\u953 \'e9 \u964 \'f4\u959 \'ef\u8059 ?\u964 \'f4\u969 \'f9\u957 \'ed \u7952 ?\u960 \'f0\u953 \'e9\u963 \'f3\u954 \'ea\u8051 ?\u968 \'f8\u949 \'e5\u969 \'f9\u962 \'f2 \u954 \'ea\u945 \'e1\u8054 ? \u952 \'e8\u949 \'e5\u969 \'f