ain \f1\scaps\lang1033\fs24 J. von Arnim\plain \f1\lang1033\fs24 , Dionis Prusaensis quem vocant Chrysostomum quae exstant omnia, I, Berlin 1893, S. XIII. \endash \plain \f1\scaps\lang1033\fs24 H. Schenkl\plain \f1\lang1033\fs24 , Die handschriftliche \u220 \'dcberlieferung der Reden des Themistius, in: Wiener Studien 20 (1898), S. 205, 210, 214, 217\endash 219, 224; ebd. 21 (1899), S. 225\endash 229, 242\endash 253, 260, 262\endash 263. \endash \plain \f1\scaps\lang1033\fs24 Vogel \plain \f1\scaps\lang1033\fs24 \endash \plain \f1\scaps\lang1033\fs24 Gardthausen\plain \f1\lang1033\fs24 , S. 315. \endash \plain \f1\scaps\lang1033\fs24 Hartig\plain \f1\lang1033\fs24 , S. 136, 243\endash 245, 367, 409. \endash \plain \f1\scaps\lang1033\fs24 H. Schenkl\plain \f1\lang1033\fs24 , Beitr\u228 \'e4ge zur Textgeschichte der Reden des Themistius, in: Sitzungsberichte der \u214 \'d6sterr. Akad. der Wiss. in Wien, Philos.-hist. Kl. 192, 1, Wien 1919, S. 54. \endash \plain \f1\scaps\lang1033\fs24 F. Cumont\plain \f1\lang1033\fs24 , Antiochus d\rquote Ath\u232 \'e8nes et Porphyre, in: Annuaire de l\rquote Institut de Philologie et d\rquote Histoire Orientales 2 (1934) = M\u233 \'e9langes Bidez I, S. 147. \endash \plain \f1\scaps\lang1033\fs24 E. R. Dodds\plain \f1\lang1033\fs24  (Hrsg.), Proclus, The Elements of Theology, Oxford \plain \f1\super\lang1033\fs48 2\plain \f1\lang1033\fs24  1963, S. XLI. \endash \plain \f1\scaps\lang1033\fs24 S. Oppermann\plain \f1\lang1033\fs24  (Hrsg.), \plain \f2\lang1032\fs24 \u920 \'c8\u917 \'c5\u924 \'cc\u921 \'c9\u931 \'d3\u932 \'d4\u921 \'c9\u927 \'cf\u931 \'d3,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u921 \'c9.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u917 \'c5\u921 \'c9\u931 \'d3\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u932 \'d4\u927 \'cf\u925 \'cd\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u913 \'c1\u933 \'d5\u932 \'d4\u927 \'cf\u933 \'d5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u928 \'d0\u91