\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\lang1033\fs24  5. (ff. 20r\endash 27v) In dominicam I quadragesimae (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u8135 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8061 ?\u964 \'f4\u8131 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7937 ?\u947 \'e3\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u957 \'ed\u951 \'e7\u963 \'f3\u964 \'f4\u949 \'e5\u953 \'e9\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7972 ?\u964 \'f4\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8000 ?\u961 \'f1\u952 \'e8\u959 \'ef\u948 \'e4\u959 \'ef\u958 \'ee\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u959 \'ef\u966 \'f6\u969 \'f9\u964 \'f4\u8049 ?\u964 \'f4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u955 \'eb\u959 \'ef\u947 \'e3\u953 \'e9\u969 \'f9\u964 \'f4\u8049 ?\u964 \'f4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u934 \'d6\u953 \'e9\u955 \'eb\u959 \'ef\u952 \'e8\u8051 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u967 \'f7\u953 \'e9\u949 \'e5\u960 \'f0\u953 \'e9\u963 \'f3\u954 \'ea\u8057 ?\u960 \'f0\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u922 \'ca\u969 \'f9\u957 \'ed\u963 \'f3\u964 \'f4\u945 \'e1\u957 \'ed\u964 \'f4\u953 \'e9\u957 \'ed\u959 \'ef\u965 \'f5\u960 \'f0\u8057 ?\u955 \'eb\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u959 \'ef\u7984 ?\u954 \'ea\u959 \'ef\u965 \'f5\u956 \'ec\u949 \'e5\u957 \'ed\u953 \'e9\u954 \'ea\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u964 \'f4\u961 \'f1\u953 \'e9\u8049 ?\u961 \'f1\u967 \'f7\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u963 \'f3\u964 \'f4\u949 \'e5\u8055 ?\u955 \'eb\u969 \'f9\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  [!] \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7937 ?\u947 \'e3\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u960 \'f0\u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u954 \'ea\u8057 ?\u957 \'ed\u969 \'f9\u957 \'ed\u903 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u955 \'eb\u8057 ?\u947 \'e3\u951 \'e7\u963 \'f3\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8051 ?\u963 \'f3\u960 \'f0\u959 \'ef\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24 ), edd. \plain \f1\scaps\lang1033\fs24 C. Triantafillis\plain \f1\lang1033\fs24  \endash A. \plain \f1\scaps\lang1033\fs24 Grapputo\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u931 \'d3\u965 \'f5\u955 \'eb\u955 \'eb\u959 \'ef\u947 \'e3\u8052 ?\plain \f1\lang1033\fs24  \u8190 ?\plain \f2\lang1032\fs24 \u917 \'c5\u955 \'eb\u955 \'eb\u951 \'e7\u957 \'ed\u953 \'e9\u954 \'ea\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8127 ?\u913 \'c1\u957 \'ed\u949 \'e5\u954 \'ea\u948 \'e4\u8057 ?\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 , I, Venedig 1874, S. 47\endash 61.}

