\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\lang1033\fs24  9. (ff. 41v\endash 45v) In dominicam V quadragesimae (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u951 \'e7\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\plain \f3\super\lang1033\fs24 \u8131 ?\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u957 \'ed\u951 \'e7\u963 \'f3\u964 \'f4\u949 \'e5\u953 \'e9\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u934 \'d6\u953 \'e9\u955 \'eb\u959 \'ef\u952 \'e8\u8051 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8165 ?\u951 \'e7\u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u945 \'e1\u947 \'e3\u947 \'e3\u949 \'e5\u955 \'eb\u8055 ?\u959 \'ef\u965 \'f5\u903 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u955 \'eb\u8057 ?\u947 \'e3\u951 \'e7\u963 \'f3\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8051 ?\u963 \'f3\u960 \'f0\u959 \'ef\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc. \plain \f2\lang1032\fs24 \u928 \'d0\u945 \'e1\u961 \'f1\u8134 ?\u955 \'eb\u952 \'e8\u949 \'e5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u8050 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u8001 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u967 \'f7\u949 \'e5\u953 \'e9\u956 \'ec\u8061 ?\u957 \'ed,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8050 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7956 ?\u945 \'e1\u961 \'f1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u963 \'f3\u8134 ?\u955 \'eb\u952 \'e8\u949 \'e5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u955 \'eb\u8051 ?\u960 \'f0\u959 \'ef\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u8055 ?\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u952 \'e8\u8049 ?\u955 \'eb\u955 \'eb\u959 \'ef\u965 \'f5\u963 \'f3\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u7936 ?\u955 \'eb\u955 \'eb\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u8052 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8004 ?\u957 \'ed\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u959 \'ef\u963 \'f3\u964 \'f4\u8055 ?\u952 \'e8\u951 \'e7\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\u8049 ?\u903 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u945 \'e1\u8166 ?\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8055 ?\u957 \'ed\u965 \'f5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u950 \'e6\u951 \'e7\u955 \'eb\u8061 ?\u963 \'f3\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u950 \'e6\u951 \'e7\u964 \'f4\u8053 ?\u963 \'f3\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7989 ?\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u959 \'ef\u8059 ?\u963 \'f3\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u950 \'e6\u969 \'f9\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u959 \'ef\u955 \'eb\u945 \'e1\u8059 ?\u963 \'f3\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u955 \'eb\u955 \'eb\u959 \'ef\u8059 ?\u963 \'f3\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8057 ?\u958 \'ee\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u8059 ?\u967 \'f7\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\u903 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u967 \'f7\u8049 ?\u961 \'f1\u953 \'e9\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u966 \'f6\u953 \'e9\u955 \'eb\u945 \'e1\u957 \'ed\u952 \'e8\u961 \'f1\u969 \'f9\u960 \'f0\u8055 ?\u8115 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

