\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\lang1033\fs24  17. (ff. 71r\endash 74v) In dominicam caeci (Ms. \plain \f2\lang1032\fs24 \u932 \'d4\u951 \'e7\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u951 \'e7\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u965 \'f5\u966 \'f6\u955 \'eb\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u932 \'d4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u969 \'f9\u964 \'f4\u8134 ?\u961 \'f1\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f4\lang1033\fs24 \u8127 ?\plain \f2\lang1032\fs24 \u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u945 \'e1\u955 \'eb\u949 \'e5\u947 \'e3\u959 \'ef\u956 \'ec\u8051 ?\u957 \'ed\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24  \u8127 ?\plain \f2\lang1032\fs24 \u921 \'c9\u959 \'ef\u965 \'f5\u948 \'e4\u945 \'e1\u8055 ?\u959 \'ef\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\u8150 ?\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u963 \'f3\u8049 ?\u958 \'ee\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u957 \'ed\u965 \'f5\u956 \'ec\u966 \'f6\u8182 ?\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u967 \'f7\u945 \'e1\u961 \'f1\u8055 ?\u963 \'f3\u949 \'e5\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8057 ?\u955 \'eb\u945 \'e1\u965 \'f5\u963 \'f3\u953 \'e9\u957 \'ed,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7975 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u8051 ?\u957 \'ed\u959 \'ef\u953 \'e9\u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u8049 ?\u957 \'ed\u964 \'f4\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\u8118 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u965 \'f5\u967 \'f7\u949 \'e5\u8150 ?\u957 \'ed\plain \f1\lang1033\fs24  \u183 \'b7 \plain \f2\lang1032\fs24 \u967 \'f7\u8049 ?\u961 \'f1\u953 \'e9\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u966 \'f6\u953 \'e9\u955 \'eb\u945 \'e1\u957 \'ed\u952 \'e8\u961 \'f1\u969 \'f9\u960 \'f0\u8055 ?\u8115 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

