\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\lang1033\fs24  24. (ff. 97v\endash 101r) In dominicam V Matthaei (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u8052 ?\plain \f1\lang1033\fs24  [!] \plain \f2\lang1032\fs24 \u949 \'e5\plain \f2\super\lang1032\fs24 \u951 \'e7\plain \f1\lang1033\fs24  \u180 \'b4); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u928 \'d0\u951 \'e7\u947 \'e3\u8052 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u957 \'ed\u949 \'e5\u965 \'f5\u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\u954 \'ea\u8052 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u969 \'f9\u964 \'f4\u8053 ?\u961 \'f1\u953 \'e9\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u953 \'e9\u954 \'ea\u955 \'eb\u8059 ?\u950 \'e6\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\plain \f3\lang1033\fs24 \u8118 ?\plain \f2\lang1032\fs24 \u962 \'f2,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u948 \'e4\u949 \'e5\u955 \'eb\u966 \'f6\u959 \'ef\u8055 ?\plain \f3\lang1033\fs24 ,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u945 \'e1\u961 \'f1\u954 \'ea\u953 \'e9\u954 \'ea\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u8049 ?\u961 \'f1\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8057 ?\u952 \'e8\u949 \'e5\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u7936 ?\u8147 ?\plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\u949 \'e5\plain \f3\lang1033\fs24 \u8150 ?\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\plain \f3\lang1033\fs24 \u8150 ?\plain \f2\lang1032\fs24 \u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u966 \'f6\u8182 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\u948 \'e4\u951 \'e7\u956 \'ec\u8053 ?\u963 \'f3\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u8183 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8127 ?\u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u8055 ?\u8179 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed,\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u8103 ?\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u7969 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8057 ?\u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

