\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\lang1033\fs24  29. (ff. 116v\endash 120v) In dominicam X Matthaei (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u951 \'e7\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u953 \'e9\plain \f2\super\lang1032\fs24 \u951 \'e7\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u924 \'cc\u945 \'e1\u964 \'f4\u952 \'e8\u945 \'e1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24  \u8190 ?\plain \f2\lang1032\fs24 \u933 \'d5\u960 \'f0\u8050 ?\u961 \'f1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f3\lang1033\fs24 \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u968 \'f8\u965 \'f5\u967 \'f7\u953 \'e9\u954 \'ea\plain \f3\lang1033\fs24 \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u969 \'f9\u964 \'f4\u951 \'e7\u961 \'f1\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8000 ?\u966 \'f6\u949 \'e5\u8055 ?\u955 \'eb\u959 \'ef\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u960 \'f0\u959 \'ef\u965 \'f5\u948 \'e4\u8049 ?\u950 \'e6\u949 \'e5\u953 \'e9\u957 \'ed,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u960 \'f0\u951 \'e7\u964 \'f4\u959 \'ef\u8055 ?,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\plain \f3\lang1033\fs24 \u8118 ?\plain \f2\lang1032\fs24 \u963 \'f3\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u949 \'e5\u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u959 \'ef\u961 \'f1\u952 \'e8\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u963 \'f3\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u965 \'f5\u957 \'ed\u951 \'e7\u952 \'e8\u8051 ?\u957 \'ed\u964 \'f4\u949 \'e5\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u955 \'eb\u955 \'eb\u8057 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u8059 ?\u967 \'f7\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u969 \'f9\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \u8127 ?\plain \f2\lang1032\fs24 \u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u8055 ?\u8179 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed,\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u8103 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8051 ?\u960 \'f0\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\plain \f3\lang1033\fs24 \u8118 ?\plain \f2\lang1032\fs24 \u963 \'f3\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8057 ?\u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

