\'f4\u955 \'eb.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u959 \'ef\u8023 ?\u964 \'f4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u8051 ?\u947 \'e3\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u955 \'eb\u951 \'e7\u952 \'e8\u8053 ?\u963 \'f3\u949 \'e5\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f3\lang1033\fs24 \u8135 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8055 ?\u8115 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u959 \'ef\u8016 ?\u961 \'f1\u945 \'e1\u957 \'ed\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7975 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u8051 ?\u957 \'ed\u959 \'ef\u953 \'e9\u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u8049 ?\u957 \'ed\u964 \'f4\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f3\lang1033\fs24 \u8118 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u965 \'f5\u967 \'f7\u949 \'e5\plain \f3\lang1033\fs24 \u8150 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u969 \'f9\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \u8127 ?\plain \f2\lang1032\fs24 \u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f3