\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\lang1033\fs24  43. (ff. 166v\endash 170v) In dominicam VIII Lucae (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u951 \'e7\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u951 \'e7\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u923 \'cb\u959 \'ef\u965 \'f5\u954 \'ea\plain \f3\lang1033\fs24 \u8118 ?\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u924 \'cc\u8051 ?\u947 \'e3\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u949 \'e5\u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u956 \'ec\u960 \'f0\u8057 ?\u948 \'e4\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u7969 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8017 ?\u960 \'f0\u949 \'e5\u961 \'f1\u951 \'e7\u966 \'f6\u945 \'e1\u957 \'ed\u8055 ?\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u7969 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7956 ?\u960 \'f0\u945 \'e1\u961 \'f1\u963 \'f3\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u954 \'ea\u8057 ?\u955 \'eb\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u945 \'e1\plain \f1\lang1033\fs24  <\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  >\plain \f2\lang1032\fs24 \u964 \'f4\u945 \'e1\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f3\lang1033\fs24 \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u949 \'e5\u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8001 ?\u948 \'e4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8001 ?\u948 \'e4\u951 \'e7\u947 \'e3\u959 \'ef\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u969 \'f9\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ? \plain \f1\lang1033\fs24  \u8127 ?\plain \f2\lang1032\fs24 \u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u8055 ?\u8179 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed,\plain \f1\lang1033\fs24  \plain \f3\lang1033\fs24 \u8103 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8051 ?\u960 \'f0\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8057 ?\u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

