\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\lang1033\fs24  44. (ff. 171r\endash 174v) In dominicam IX Lucae (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u951 \'e7\plain \f4\lang1033\fs24 `\plain \f3\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u952 \'e8\plain \f3\super\lang1033\fs24 \u8131 ?\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u923 \'cb\u959 \'ef\u965 \'f5\u954 \'ea\plain \f3\lang1033\fs24 \u8118 ?\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc. \u8190 ?\plain \f2\lang1032\fs24 \u919 \'c7\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u955 \'eb\u949 \'e5\u959 \'ef\u957 \'ed\u949 \'e5\u958 \'ee\u8055 ?\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u8051 ?\u947 \'e3\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8150 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u952 \'e8\u961 \'f1\u8061 ?\u960 \'f0\u959 \'ef\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u954 \'ea\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u959 \'ef\u8016 ?\u948 \'e4\u8050 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\plain \f3\lang1033\fs24 \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8017 ?\u960 \'f0\u8049 ?\u961 \'f1\u967 \'f7\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u949 \'e5\u953 \'e9\u957 \'ed\u8057 ?\u964 \'f4\u949 \'e5\u961 \'f1\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u959 \'ef\u8021 ?\u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u955 \'eb\u960 \'f0\u8055 ?\u950 \'e6\u959 \'ef\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u955 \'eb\u955 \'eb\u8057 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\u949 \'e5\u8055 ?\u957 \'ed\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u970 \'fa\u948 \'e4\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u949 \'e5\u8059 ?\u958 \'ee\u949 \'e5\u963 \'f3\u952 \'e8\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \u183 \'b7 \plain \f2\lang1032\fs24 \u967 \'f7\u8049 ?\u961 \'f1\u953 \'e9\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u966 \'f6\u953 \'e9\u955 \'eb\u945 \'e1\u957 \'ed\u952 \'e8\u961 \'f1\u969 \'f9\u960 \'f0\u8055 ?\u8115 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\plain \f3\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f4\lang1033\fs24 \u8127 ?\plain \f2\lang1032\fs24 \u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8166 ?,\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8103 ? \u7969 ? \u948 \'e4\u8057 ?\u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

